<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/research-knowledge.php';require_once __DIR__.'/app/research-intelligence.php';require_once __DIR__.'/app/research-entities.php';require_once __DIR__.'/app/ai.php';require_once __DIR__.'/app/ai-access.php';require_once __DIR__.'/app/research-workspace.php';
$u=require_user($pdo);$id=(string)($_GET['id']??$_POST['id']??'');$project=project_access($pdo,(int)$u['id'],$id);if(!$project){http_response_code(404);exit('Research project not found.');}$canWrite=project_can_write($project);$success='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$op=(string)($_POST['op']??'');try{
    if(!$canWrite)throw new RuntimeException('You have view-only access to this project.');
    if($op==='create_entity'){
        $entity=research_entity_upsert($pdo,(int)$project['id'],(int)$u['id'],(string)($_POST['name']??''),(string)($_POST['entity_type']??'other'),trim((string)($_POST['description']??''))?:null,'manual');if(research_workspace_ready($pdo))research_workspace_queue($pdo,(int)$project['id'],3);header('Location:/research-entity.php?id='.rawurlencode((string)$entity['public_id']));exit;
    }
    if($op==='add_relation'){
        $source=research_project_entity_target($pdo,(int)$project['id'],(string)($_POST['source_entity']??''));$target=research_project_entity_target($pdo,(int)$project['id'],(string)($_POST['target_entity']??''));$type=(string)($_POST['relation_type']??'related_to');
        if(!$source||!$target)throw new RuntimeException('Both entities must belong to this Research project.');if((int)$source['id']===(int)$target['id'])throw new RuntimeException('An entity cannot relate to itself.');if(!in_array($type,research_entity_relation_types(),true))throw new RuntimeException('Invalid entity relationship.');
        $pdo->prepare('INSERT INTO research_entity_relations(public_id,project_id,source_entity_id,target_entity_id,added_by_user_id,relation_type,note) VALUES(?,?,?,?,?,?,?)')->execute([ulid_like(),$project['id'],$source['id'],$target['id'],$u['id'],$type,trim((string)($_POST['note']??''))?:null]);$success='Entity relationship added.';
    }
    if($op==='remove_relation'){$pdo->prepare('DELETE FROM research_entity_relations WHERE public_id=? AND project_id=?')->execute([(string)($_POST['relation']??''),$project['id']]);$success='Entity relationship removed.';}
    if($op==='extract_ai'){
        if(!user_is_pro($pdo,$u))throw new RuntimeException('AI entity extraction is available to Pro users.');$isAdmin=($u['role']??'')==='admin';$quota=rate_limit_consume($pdo,$isAdmin?'ai-admin':'ai-pro','user:'.(string)$u['id'],$isAdmin?240:40,3600);if(!$quota['allowed'])throw new RuntimeException('AI request limit reached. Try again later.');
        $model=ai_setting_model_id($pdo,'research',true);if(!$model)$model=ai_setting_model_id($pdo,'pro',true);if(!$model)throw new RuntimeException('No Pro research model is configured.');ai_interactive_model_record($pdo,$u,$model);
        $raw=ai_research_context($pdo,(int)$project['id']);$knowledge=research_knowledge_ai_context($pdo,(int)$project['id']);$intel=research_intelligence_ai_context($pdo,(int)$project['id']);$existing=research_entity_graph_ai_context($pdo,(int)$project['id']);
        $system='You are Annotated Entity Extractor. Use only supplied Research project context. Return JSON only, no markdown. Extract only useful research entities. Entity types: person, company, organization, place, event, topic, date, other. Every extracted entity should include exact refs using only SOURCE, ANNOTATION, CLAIM, or FINDING IDs that appear in context. Never invent IDs. Entity relationships are suggestions, not facts. Include every entity used by a relationship in the entities array. Schema: {"entities":[{"name":"","type":"person","description":"","refs":[{"type":"SOURCE","id":""}]}],"relationships":[{"source":"","source_type":"person","relation":"related_to","target":"","target_type":"organization","note":""}]}. Allowed relationships: related_to, part_of, located_in, works_for, owns, involved_in, occurred_at, associated_with.';
        $prompt="Project: {$project['title']}\n\nSOURCE/ANNOTATION CONTEXT:\n{$raw['text']}\n\nCLAIMS/FINDINGS:\n{$knowledge['text']}\n\nCLAIM GRAPH/SNAPSHOT:\n{$intel['text']}\n\nEXISTING ENTITY GRAPH:\n{$existing['text']}";
        $run=ai_run($pdo,$config,$u,$isAdmin?'admin':'pro','research_entity_extraction',$model,$system,$prompt,array_merge($raw['refs'],$knowledge['refs'],$intel['refs'],$existing['refs']),'research_project',$project['public_id']);$data=research_parse_entity_json((string)$run['text']);
        $pdo->beginTransaction();$applied=research_apply_ai_entities($pdo,(int)$project['id'],(int)$u['id'],$data,(string)$run['public_id']);$pdo->commit();$success="AI suggested {$applied['entities']} entities, attached {$applied['mentions']} project references, and added {$applied['relations']} relationships. Review Suggested entities before relying on them.";
    }
    if($success!==''&&research_workspace_ready($pdo))research_workspace_queue($pdo,(int)$project['id'],3);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$entities=research_project_entity_rows($pdo,(int)$project['id']);$relations=research_entity_relation_rows($pdo,(int)$project['id']);$counts=[];$suggested=0;foreach($entities as $e){$counts[$e['entity_type']]=($counts[$e['entity_type']]??0)+1;if($e['status']==='suggested')$suggested++;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Entity Graph · <?=h($project['title'])?> · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/home.php">Annotated</a><nav><a href="/research-knowledge.php?id=<?=h($project['public_id'])?>">Knowledge</a><a href="/research-graph.php?id=<?=h($project['public_id'])?>">Claim Graph</a><a href="/research-brief.php?id=<?=h($project['public_id'])?>">Brief</a><a href="/research.php">Research</a></nav></header><main class="layout"><section><div class="pageTitle"><span class="eyebrow">ENTITY KNOWLEDGE GRAPH · <?=h(strtoupper($project['access_role']))?></span><h1><?=h($project['title'])?></h1><p>Connect people, organizations, companies, places, events, topics and dates back to the exact project objects where they appear.</p></div><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
<div class="card"><div class="meta">ENTITY SUMMARY</div><p><?=count($entities)?> active entities · <?=h((string)$suggested)?> awaiting confirmation · <?=count($relations)?> relationships<?php foreach($counts as $type=>$n):?> · <?=h((string)$n)?> <?=h($type)?><?php endforeach?></p></div>
<h2>Entities</h2><?php if(!$entities):?><div class="card empty">No entities yet. Add one manually or use Pro extraction against this project's existing evidence.</div><?php endif?><?php foreach($entities as $e):?><article class="card"><div class="meta"><?=h(strtoupper($e['entity_type']))?> · <?=h(strtoupper($e['status']))?> · <?=h((string)$e['mention_count'])?> references · <?=h((string)$e['relation_count'])?> relationships · <?=h(strtoupper($e['source_type']))?></div><h3><a href="/research-entity.php?id=<?=h($e['public_id'])?>"><?=h($e['canonical_name'])?></a></h3><?php if($e['description']):?><p><?=nl2br(h($e['description']))?></p><?php endif?></article><?php endforeach?>
<h2>Entity relationships</h2><?php if(!$relations):?><div class="card empty">No entity relationships yet.</div><?php endif?><?php foreach($relations as $r):?><article class="card"><div class="meta"><?=h(strtoupper(str_replace('_',' ',$r['relation_type'])))?> · <?=h($r['created_at'])?></div><p><a href="/research-entity.php?id=<?=h($r['source_public_id'])?>"><?=h($r['source_name'])?></a> <strong>→ <?=h(str_replace('_',' ',$r['relation_type']))?> →</strong> <a href="/research-entity.php?id=<?=h($r['target_public_id'])?>"><?=h($r['target_name'])?></a></p><?php if($r['note']):?><p><?=nl2br(h($r['note']))?></p><?php endif?><?php if($canWrite):?><form method="post" class="inlineForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="remove_relation"><input type="hidden" name="relation" value="<?=h($r['public_id'])?>"><button>Remove</button></form><?php endif?></article><?php endforeach?></section><aside><?php if($canWrite):?><div class="card"><h3>New Entity</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="create_entity"><label>Name<input name="name" required></label><label>Type<select name="entity_type"><?php foreach(research_entity_types() as $type):?><option value="<?=h($type)?>"><?=h(ucfirst($type))?></option><?php endforeach?></select></label><label>Description<textarea name="description" rows="3"></textarea></label><button>Create Entity</button></form></div><?php endif?><?php if($canWrite&&user_is_pro($pdo,$u)):?><div class="card"><h3>Extract Entities</h3><p class="meta">AI suggestions are limited to this project's existing context and remain Suggested until a researcher confirms them.</p><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="extract_ai"><button>Extract from Project</button></form></div><?php endif?><?php if($canWrite&&count($entities)>1):?><div class="card"><h3>Connect Entities</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="add_relation"><label>Source<select name="source_entity" required><option value="">Choose entity</option><?php foreach($entities as $e):?><option value="<?=h($e['public_id'])?>"><?=h($e['canonical_name'])?> · <?=h($e['entity_type'])?></option><?php endforeach?></select></label><label>Relationship<select name="relation_type"><?php foreach(research_entity_relation_types() as $type):?><option value="<?=h($type)?>"><?=h(ucwords(str_replace('_',' ',$type)))?></option><?php endforeach?></select></label><label>Target<select name="target_entity" required><option value="">Choose entity</option><?php foreach($entities as $e):?><option value="<?=h($e['public_id'])?>"><?=h($e['canonical_name'])?> · <?=h($e['entity_type'])?></option><?php endforeach?></select></label><label>Note<textarea name="note" rows="3"></textarea></label><button>Add relationship</button></form></div><?php endif?><div class="card"><h3>Review rule</h3><p class="meta">AI extraction is discovery assistance. Suggested entities and relationships are authored structure, not independent evidence. Confirm important entities and inspect their exact references.</p></div></aside></main></body></html>
